// Decode the current gpu-rental-prices.json fetched from GitHub
const b64 = ($json.content || "").replace(/\n/g, "");
const text = Buffer.from(b64, "base64").toString("utf-8");
const current = JSON.parse(text);
return [{ json: { current, sha: $json.sha } }];

// Build the Anthropic Messages API request (Claude + web search)
const current = $json.current;
const today = new Date().toISOString().slice(0, 10);
const month = today.slice(0, 7);

const prompt = [
  "You are refreshing GridTilt's GPU rental price dataset. Today is " + today + ".",
  "",
  "Here is the CURRENT dataset JSON:",
  JSON.stringify(current, null, 2),
  "",
  "Using web search, update the on-demand rental price for EACH of the " + current.models.length +
    " models to reflect this month (" + month + "), across neoclouds and GPU marketplaces (getdeploying.com, Silicon Data, aimultiple, Lambda, RunPod, Vast.ai, CoreWeave, Together, Hyperstack, TensorWave, Vultr, Nebius, DigitalOcean).",
  "",
  "Rules:",
  "- currentUsdPerHr is a BLENDED neocloud/marketplace on-demand estimate. Keep hyperscaler list prices (AWS, Azure, Oracle) inside \"high\" but do NOT let them drive the representative value.",
  "- Update low and high to the observed marketplace range you actually find this month.",
  "- Refresh oneYearTrend to one sourced sentence and refresh sources to 3-4 real https URLs you actually checked.",
  "- PRESERVE every existing historyAnchors entry exactly, and APPEND one new anchor {\"date\":\"" + month + "\",\"price\":<new currentUsdPerHr>} (overwrite only if a " + month + " anchor already exists).",
  "- Keep model, vendor, architecture, vramGB, vramType, launchYear unless you have a sourced correction.",
  "- Only report prices you find. Do not invent precision. If a model is barely listed, set confidence \"low\".",
  "- Set lastRefreshed to \"" + today + "\" and each model's asOf to \"" + month + "\".",
  "",
  "Output ONLY the full updated JSON object (same shape and same models in the same order), no prose and no markdown fences."
].join("\n");

const requestBody = {
  model: "claude-sonnet-4-6",
  max_tokens: 8000,
  tools: [{ type: "web_search_20250305", name: "web_search", max_uses: 12 }],
  messages: [{ role: "user", content: prompt }]
};
return [{ json: { requestBody } }];

// Parse Claude's response, then HARD-VALIDATE before anything can be committed.
const resp = $json;
let text = "";
if (Array.isArray(resp.content)) {
  for (const b of resp.content) { if (b.type === "text" && b.text) text += b.text; }
} else if (typeof resp.content === "string") {
  text = resp.content;
}
text = text.trim();
const s = text.indexOf("{");
const e = text.lastIndexOf("}");
if (s === -1 || e === -1) throw new Error("No JSON found in Claude response");
const obj = JSON.parse(text.slice(s, e + 1));

const prev = $("Decode current file").item.json.current;
const prevByModel = Object.fromEntries(prev.models.map((m) => [m.model, m]));

if (!Array.isArray(obj.models) || obj.models.length !== prev.models.length) {
  throw new Error("model count changed: " + ((obj.models || []).length) + " vs " + prev.models.length);
}
for (const m of obj.models) {
  const p = prevByModel[m.model];
  if (!p) throw new Error("unknown / renamed model: " + m.model);
  if (typeof m.currentUsdPerHr !== "number" || m.currentUsdPerHr <= 0 || m.currentUsdPerHr > 80)
    throw new Error(m.model + " current out of range: " + m.currentUsdPerHr);
  if (!(m.low <= m.currentUsdPerHr && m.currentUsdPerHr <= m.high))
    throw new Error(m.model + " range invalid: " + m.low + " <= " + m.currentUsdPerHr + " <= " + m.high);
  if (!Array.isArray(m.sources) || m.sources.length < 1 || !m.sources.every((x) => /^https:\/\//.test(x)))
    throw new Error(m.model + " bad/empty sources");
  if (!Array.isArray(m.estimated) || !m.estimated.includes("currentUsdPerHr"))
    throw new Error(m.model + " missing est. flag");
  if (!Array.isArray(m.historyAnchors) || m.historyAnchors.length < p.historyAnchors.length)
    throw new Error(m.model + " history anchors shrank");
  const chg = Math.abs(m.currentUsdPerHr - p.currentUsdPerHr) / p.currentUsdPerHr;
  if (chg > 0.6)
    throw new Error(m.model + " moved >60% (" + p.currentUsdPerHr + " -> " + m.currentUsdPerHr + "); blocked for manual review");
}

obj.lastRefreshed = new Date().toISOString().slice(0, 10);
const fileContent = JSON.stringify(obj, null, 2) + "\n";

let changed = 0;
const lines = obj.models.map((m) => {
  const p = prevByModel[m.model];
  const d = m.currentUsdPerHr - p.currentUsdPerHr;
  if (Math.abs(d) >= 0.005) changed++;
  const sign = d > 0 ? "+" : "";
  return m.model + ": $" + p.currentUsdPerHr + " -> $" + m.currentUsdPerHr + " (" + sign + d.toFixed(2) + ")";
});
const summary = "GridTilt GPU prices refreshed " + obj.lastRefreshed + " (" + changed + " moved):\n" + lines.join("\n");
return [{ json: { fileContent, summary } }];

// Base64-encode the validated file and assemble the GitHub commit payload
const content = $json.fileContent;
const b64 = Buffer.from(content, "utf-8").toString("base64");
const sha = $("Decode current file").item.json.sha;
const commitBody = {
  message: "Neocloud Intel: weekly GPU price refresh (" + new Date().toISOString().slice(0, 10) + ")",
  content: b64,
  sha,
  branch: "main"
};
return [{ json: { commitBody, summary: $json.summary } }];
